orb -m ubuntu python3 -B - <<'PY'
from pathlib import Path
import json
r={}
for name in ['/sys/bus/event_source/devices','/dev']:
 p=Path(name)
 r[name]=sorted(x.name for x in p.iterdir() if name.endswith('devices') or any(y in x.name.lower() for y in ['perf','pmu','kvm']))
r['event_sources']={}
for p in sorted(Path('/sys/bus/event_source/devices').iterdir()):
 d={}
 for rel in ['type','cpumask','cpus','caps/pmu_name','caps/nr_addr_filters']:
  q=p/rel
  if q.is_file():d[rel]=q.read_text().strip()
 for rel in ['events','format']:
  q=p/rel
  if q.is_dir():d[rel]={f.name:f.read_text().strip() for f in sorted(q.iterdir()) if f.is_file()}
 r['event_sources'][p.name]=d
for rel in ['/proc/sys/kernel/perf_event_paranoid','/proc/sys/kernel/perf_event_max_sample_rate','/proc/sys/kernel/perf_event_max_stack','/proc/sys/kernel/nmi_watchdog','/sys/devices/system/cpu/online','/sys/devices/system/cpu/cpu0/regs/identification/midr_el1','/proc/self/status']:
 p=Path(rel)
 if p.exists():
  value=p.read_text().strip()
  if rel.endswith('/status'):value='\n'.join(x for x in value.splitlines() if x.startswith(('Cap','Seccomp','NoNewPrivs')))
  r[rel]=value
print(json.dumps(r,indent=2))
